        dlg("h06_60", "act4", "student_lin", "林致远", "[warmly] 敬红绿灯，也敬那位远在大西洋彼岸、愿意跟老朋友坦诚辩论的凯恩斯爵士！谢谢您，哈耶克教授！", gap_after_s=0.24),
